vertexShader:
attribute vec3 iPos; attribute vec3 iCol; attribute float iSize; attribute float iOp; varying vec2 vUv; varying vec3 vCol; varying float vOp;
        #include <fog_pars_vertex>
        void main() { vUv = uv; vCol = iCol; vOp = iOp; vec4 mvPosition = modelViewMatrix * vec4(iPos, 1.); mvPosition.xy += position.xy * iSize; gl_Position = projectionMatrix * mvPosition;
          #include <fog_vertex>
        }

fragmentShader:
uniform sampler2D map; uniform float uOp; varying vec2 vUv; varying vec3 vCol; varying float vOp;
        #include <fog_pars_fragment>
        void main() { vec4 t = texture2D(map, vUv); gl_FragColor = vec4(vCol * t.rgb, t.a * vOp * uOp);
          #include <tonemapping_fragment>
          #include <colorspace_fragment>
          #include <fog_fragment>
        }
